const $=s=>document.querySelector(s);
const states={nature:{image:'nature',alt:'Parcela ficticia con vegetación, imagen generada',eyebrow:'EL PUNTO DE PARTIDA / ESCENA DE EJEMPLO',title:'Todo empieza<br><em>con una posibilidad.</em>',status:'Visualización del lote con vegetación. No es una captura real.'},clean:{image:'clean',alt:'Misma parcela ficticia despejada, imagen generada',eyebrow:'LIMPIEZA PROYECTADA / ESCENA DE EJEMPLO',title:'Espacio para<br><em>lo que imaginas.</em>',status:'Así se presenta la limpieza proyectada del terreno.'},house:{image:'house',alt:'Render conceptual de Casa Alba en un lote arbolado',eyebrow:'UNA POSIBILIDAD / RENDER CONCEPTUAL',title:'Aquí podría empezar<br><em>tu próxima historia.</em>',status:'Una visión de la vivienda terminada en su entorno.'}};
let state='house',view='photo',comparing=false,threeModule,model,pano,currentRoom='living',panoRequest=0;
const rooms={living:{index:'01 / ÁREA SOCIAL',name:'Sala & comedor',asset:'living-pano',yaw:-.3,next:'kitchen',nextName:'Descubrir la cocina'},kitchen:{index:'02 / ÁREA SOCIAL',name:'La cocina',asset:'living-pano',yaw:.65,next:'bedroom',nextName:'Entrar al dormitorio'},bedroom:{index:'03 / ÁREA PRIVADA',name:'Tu lugar de descanso',asset:'bedroom-pano',yaw:0,next:'living',nextName:'Volver a la sala'}};
const graphics=()=>threeModule||(threeModule=import('./graphics.js?v=3').catch(e=>{threeModule=null;throw e}));
function page(which){$('#territory-view').hidden=which!=='territory';$('#lot-view').hidden=which==='territory';document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===which);if(b.closest('nav')){if(b.dataset.page===which)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}});if(which==='lot')model?.resize();}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>page(b.dataset.page)));
function syncComparison(){const value=$('#comparison-range').value;$('#before-layer').style.clipPath=`inset(0 ${100-value}% 0 0)`;$('.comparison-line').style.left=value+'%';$('.compare-label.after').textContent=state==='clean'?'LOTE LIMPIO':'CON VIVIENDA'}
function setCompare(on){comparing=on;$('#before-layer').hidden=!on;$('#comparison-ui').hidden=!on;$('#compare').setAttribute('aria-pressed',String(on));$('#visual-stage').classList.toggle('comparison-on',on);syncComparison()}
function setState(key){state=key;const d=states[key];$('#main-photo').src=`assets/${d.image}.jpg`;$('#main-photo').alt=d.alt;$('#scene-title').innerHTML=d.title;$('#scene-eyebrow').textContent=d.eyebrow;$('#scene-status').textContent=d.status;document.querySelectorAll('[data-state]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.state===key)));$('.photo-hotspot').hidden=key!=='house';if(key==='nature')setCompare(false);if(model)model.setState(key);syncComparison();}
document.querySelectorAll('[data-state]').forEach(b=>b.addEventListener('click',()=>{setState(b.dataset.state);if(view==='plan')setView('photo')}));
async function setView(key){view=key;$('#photo-stage').hidden=key!=='photo';$('#model-stage').hidden=key!=='model';$('#plan-stage').hidden=key!=='plan';$('#scene-tools').hidden=key!=='model';$('#compare').disabled=key!=='photo';$('#visual-stage').classList.toggle('model-active',key==='model');$('#visual-stage').classList.toggle('plan-active',key==='plan');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===key)));if(key!=='photo')setCompare(false);$('#render-caption').textContent=key==='photo'?'IMAGEN GENERADA / EJEMPLO':key==='model'?'MAQUETA DE ESCALA / ILUSTRATIVA':'ESQUEMA / MEDIDAS DE EJEMPLO';if(key==='model'){try{if(!model)model=(await graphics()).createLot($('#model-stage'));model.setState(state);model.resize()}catch{$('#model-stage').innerHTML='<p class="loading">La maqueta no está disponible en este dispositivo. Puedes seguir explorando en Visualización o Plano del lote.</p>';$('#scene-tools').hidden=true}}}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('#show-plan').addEventListener('click',()=>{setState('house');setView('plan');$('#visual-stage').scrollIntoView({behavior:'smooth',block:'start'})});
$('#compare').addEventListener('click',()=>{if(state==='nature')setState('house');setCompare(!comparing)});$('#comparison-range').addEventListener('input',syncComparison);
$('#orbit-left').addEventListener('click',()=>model?.turn(-.2));$('#orbit-right').addEventListener('click',()=>model?.turn(.2));$('#zoom-in').addEventListener('click',()=>model?.zoom(-5));$('#zoom-out').addEventListener('click',()=>model?.zoom(5));$('#reset-camera').addEventListener('click',()=>model?.reset());
const tour=$('#tour-dialog');
async function chooseRoom(key){currentRoom=key;const d=rooms[key];const ticket=++panoRequest;$('#room-index').textContent=d.index;$('#room-name').textContent=d.name;$('#hotspot-name').textContent=d.nextName;document.querySelectorAll('[data-room]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.room===key)));$('#tour-loading').hidden=false;$('#tour-loading').textContent='Preparando tu visita…';try{if(!pano)pano=(await graphics()).createPanorama($('#panorama'));if(ticket!==panoRequest)return;await pano.show(`assets/${d.asset}.jpg`,d.yaw);if(ticket!==panoRequest)return;$('#tour-fallback').hidden=true;$('#tour-loading').hidden=true;pano.resize()}catch{if(ticket!==panoRequest)return;$('#tour-loading').textContent='Vista estática disponible. El panorama no pudo cargarse.';$('#tour-fallback').hidden=false;$('#tour-fallback').src=`assets/${key==='bedroom'?'bedroom-pano':'living'}.jpg`;}}
function openTour(){tour.showModal();chooseRoom('living')}
document.querySelectorAll('[data-tour]').forEach(b=>b.addEventListener('click',openTour));document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>chooseRoom(b.dataset.room)));$('#room-hotspot').addEventListener('click',()=>chooseRoom(rooms[currentRoom].next));$('#look-left').addEventListener('click',()=>pano?.turn(-.2));$('#look-right').addEventListener('click',()=>pano?.turn(.2));$('#return-lot').addEventListener('click',()=>{tour.close();page('lot')});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()})});
$('#about').addEventListener('click',()=>$('#about-dialog').showModal());document.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',()=>$('#save-dialog').showModal()));$('#download-selection').addEventListener('click',()=>{const content=`RAINBOW PARK COLLECTION\nMi selección de ejemplo\n\nLote 07 + Casa Alba\nLote: 1,012 m² (aprox. ¼ acre)\nVivienda: 1 planta · 3 habitaciones · 2 baños\nHuella: 180 m²\nAcceso + terraza: 66 m²\nExterior restante: 766 m²\n\nMe gustaría conocer:\n${$('#selection-note').value||'Más información sobre una propuesta similar.'}\n\nEsta selección es conceptual. La zona, el lote, las superficies y la casa son ficticios. No equivale a una reserva ni ha sido enviada.\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mi-seleccion-rainbow-park.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#download-status').textContent='Resumen descargado. No se ha enviado información.'});
// Load the two alternate aerial states after the first image is available.
window.addEventListener('load',()=>{for(const key of ['clean','nature']){const img=new Image();img.src=`assets/${key}.jpg`}});
